package kr.or.arte.seal.retention.persistence;

import kr.or.arte.seal.recipient.application.*;import kr.or.arte.seal.request.application.*;import kr.or.arte.seal.retention.application.*;import kr.or.arte.seal.retention.domain.RetentionAnchorType;import kr.or.arte.seal.retention.domain.RetentionJobStatus;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.assertj.core.api.Assertions.assertThatCode;

@SpringBootTest @Transactional @EnabledIfEnvironmentVariable(named="SEAL_DB_PASSWORD",matches=".+")
class RetentionPostgresIntegrationTest {
 @Autowired JdbcTemplate jdbc;@Autowired RecipientManagementService recipients;@Autowired ConsentRequestManagementService requests;@Autowired RetentionJobService retention;
 @org.junit.jupiter.api.BeforeEach void ensureApprover(){jdbc.update("INSERT INTO seal.admin_user(admin_user_id,login_id,display_name,organization_unit_id,password_hash,must_change_password) SELECT ?,'vheraclesv','통합테스트 승인자',organization_unit_id,password_hash,FALSE FROM seal.admin_user WHERE login_id='seal-admin' AND NOT EXISTS(SELECT 1 FROM seal.admin_user WHERE login_id='vheraclesv')",UUID.randomUUID());jdbc.update("INSERT INTO seal.user_scope(user_scope_id,admin_user_id,scope_type,scope_target_id,include_descendants,assigned_by) SELECT gen_random_uuid(),a.admin_user_id,'ORGANIZATION',a.organization_unit_id,TRUE,s.admin_user_id FROM seal.admin_user a JOIN seal.admin_user s ON s.login_id='seal-admin' WHERE a.login_id='vheraclesv' AND NOT EXISTS(SELECT 1 FROM seal.user_scope WHERE admin_user_id=a.admin_user_id AND scope_type='ORGANIZATION' AND scope_target_id=a.organization_unit_id)");}
 @Test void acceptsMailFirstSentAtAsRetentionStartEvent(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);assertThatCode(()->jdbc.update("UPDATE seal.retention_policy_version SET start_event='MAIL_FIRST_SENT_AT' WHERE retention_policy_version_id=?",fixture.retentionVersionId())).doesNotThrowAnyException();}
 @Test void acceptsRequestExpiresAtAsRetentionStartEvent(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);assertThatCode(()->jdbc.update("UPDATE seal.retention_policy_version SET start_event='REQUEST_EXPIRES_AT' WHERE retention_policy_version_id=?",fixture.retentionVersionId())).doesNotThrowAnyException();}
 @Test void schedulesDestructionFromFirstAcceptedMailDate(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);UUID recipient=recipients.create(new CreateRecipientCommand(actor,org,"메일 기준 대상자","mail-anchor-"+UUID.randomUUID()+"@example.com","메일 기준 검증"));var request=requests.create(actor,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));UUID link=UUID.randomUUID();jdbc.update("UPDATE seal.retention_policy_version SET start_event='MAIL_FIRST_SENT_AT',period_value=1,period_unit='YEAR',grace_period_days=0 WHERE retention_policy_version_id=?",fixture.retentionVersionId());jdbc.update("UPDATE seal.consent_request SET request_status='EXPIRED',created_at=TIMESTAMPTZ '2024-01-01 00:00:00+00',expires_at=TIMESTAMPTZ '2024-01-03 00:00:00+00' WHERE consent_request_id=?",request.requestId());jdbc.update("INSERT INTO seal.secure_link(secure_link_id,consent_request_id,token_hmac,link_status,expires_at,issued_by,issued_at,expired_at) VALUES(?,?,?,'EXPIRED',TIMESTAMPTZ '2024-01-03 00:00:00+00',?,TIMESTAMPTZ '2024-01-01 00:00:00+00',TIMESTAMPTZ '2024-01-03 00:00:00+00')",link,request.requestId(),"a".repeat(64),actor);jdbc.update("INSERT INTO seal.mail_outbox(mail_outbox_id,consent_request_id,secure_link_id,recipient_email_ciphertext,html_ciphertext,encryption_key_id,mail_subject,html_sha256,mail_status,scheduled_at,next_attempt_at,smtp_accepted_at,attempt_count,created_by,created_at,updated_at) VALUES(gen_random_uuid(),?,?,decode(repeat('aa',30),'hex'),decode(repeat('bb',30),'hex'),'v1','테스트 메일',repeat('c',64),'SMTP_ACCEPTED',TIMESTAMPTZ '2024-01-02 09:00:00+00',TIMESTAMPTZ '2024-01-02 09:00:00+00',TIMESTAMPTZ '2024-01-02 09:00:00+00',1,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",request.requestId(),link,actor);retention.scheduleDue();var dates=jdbc.queryForList("SELECT anchor_date,due_date FROM seal.retention_job WHERE consent_request_id=?",request.requestId());assertThat(dates).singleElement().satisfies(row->{assertThat(row.get("anchor_date")).isEqualTo(java.sql.Date.valueOf("2024-01-02"));assertThat(row.get("due_date")).isEqualTo(java.sql.Date.valueOf("2025-01-02"));});}
 @Test void schedulesDestructionFromRequestExpiryDateWithoutResponse(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);UUID recipient=recipients.create(new CreateRecipientCommand(actor,org,"만료 기준 대상자","expiry-anchor-"+UUID.randomUUID()+"@example.com","만료 기준 검증"));var request=requests.create(actor,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));jdbc.update("UPDATE seal.retention_policy_version SET start_event='REQUEST_EXPIRES_AT',period_value=1,period_unit='YEAR',grace_period_days=0 WHERE retention_policy_version_id=?",fixture.retentionVersionId());jdbc.update("UPDATE seal.consent_request SET request_status='EXPIRED',created_at=TIMESTAMPTZ '2024-01-01 00:00:00+00',expires_at=TIMESTAMPTZ '2024-01-03 00:00:00+00' WHERE consent_request_id=?",request.requestId());retention.scheduleDue();var dates=jdbc.queryForList("SELECT anchor_date,due_date FROM seal.retention_job WHERE consent_request_id=?",request.requestId());assertThat(dates).singleElement().satisfies(row->{assertThat(row.get("anchor_date")).isEqualTo(java.sql.Date.valueOf("2024-01-03"));assertThat(row.get("due_date")).isEqualTo(java.sql.Date.valueOf("2025-01-03"));});}
 @Test void fallsBackToRequestExpiryDateWhenSubmissionBasedRecipientDoesNotRespond(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);UUID recipient=recipients.create(new CreateRecipientCommand(actor,org,"미응답 대상자","no-response-"+UUID.randomUUID()+"@example.com","미응답 기준 검증"));var request=requests.create(actor,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));jdbc.update("UPDATE seal.retention_policy_version SET start_event='CONSENT_SUBMITTED_AT',period_value=1,period_unit='YEAR',grace_period_days=0 WHERE retention_policy_version_id=?",fixture.retentionVersionId());jdbc.update("UPDATE seal.consent_request SET request_status='EXPIRED',created_at=TIMESTAMPTZ '2024-01-01 00:00:00+00',expires_at=TIMESTAMPTZ '2024-01-08 00:00:00+00' WHERE consent_request_id=?",request.requestId());retention.scheduleDue();var dates=jdbc.queryForList("SELECT anchor_date,due_date FROM seal.retention_job WHERE consent_request_id=?",request.requestId());assertThat(dates).singleElement().satisfies(row->{assertThat(row.get("anchor_date")).isEqualTo(java.sql.Date.valueOf("2024-01-08"));assertThat(row.get("due_date")).isEqualTo(java.sql.Date.valueOf("2025-01-08"));});}
 @Test void listsDestructionJobWithRecipientAndRequestCode(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);UUID recipient=recipients.create(new CreateRecipientCommand(actor,org,"목록 표시 대상자","retention-list-"+UUID.randomUUID()+"@example.com","목록 표시 검증"));var request=requests.create(actor,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));jdbc.update("INSERT INTO seal.retention_job(retention_job_id,consent_request_id,recipient_id,retention_policy_version_id,anchor_date,due_date,job_status,destruction_method,requested_at) VALUES(gen_random_uuid(),?,?,?,DATE '2026-09-03',DATE '2027-09-03','DUE','DELETE',CURRENT_TIMESTAMP)",request.requestId(),recipient,fixture.retentionVersionId());assertThat(retention.search(actor,RetentionJobStatus.DUE)).filteredOn(item->item.consentRequestId().equals(request.requestId())).singleElement().satisfies(item->{assertThat(item.recipientId()).isEqualTo(recipient);assertThat(item.requestCode()).isEqualTo(request.requestCode());assertThat(item.anchorDate()).isEqualTo(LocalDate.of(2026,9,3));});}
 @Test void executesPrimaryStoreDestructionWithSeparateActorsAndIdempotency(){UUID requester=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID approver=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='vheraclesv'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");UUID creator=fixtureCreator();Fixture fixture=publishedFixture(org,creator,requester);UUID recipient=recipients.create(new CreateRecipientCommand(requester,org,"파기 대상자","retention-"+UUID.randomUUID()+"@example.com","파기 통합테스트 수집"));var request=requests.create(requester,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));retention.recordAnchor(requester,request.requestId(),RetentionAnchorType.PROGRAM_END_AT,LocalDate.of(2026,8,1));retention.recordAnchor(requester,request.requestId(),RetentionAnchorType.PROGRAM_END_AT,LocalDate.of(2026,8,2));assertThat(jdbc.queryForObject("SELECT count(*) FROM seal.retention_anchor_event WHERE consent_request_id=? AND anchor_type='PROGRAM_END_AT'",Integer.class,request.requestId())).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM seal.retention_anchor_event WHERE consent_request_id=? AND anchor_type='PROGRAM_END_AT' AND active",Integer.class,request.requestId())).isEqualTo(1);retention.placeLegalHold(requester,request.requestId(),"AUDIT","감사 대응",LocalDate.now().plusDays(1));UUID hold=retention.activeLegalHolds(requester).stream().filter(h->h.consentRequestId().equals(request.requestId())).findFirst().orElseThrow().id();retention.releaseLegalHold(requester,hold);assertThat(jdbc.queryForObject("SELECT active FROM seal.legal_hold WHERE legal_hold_id=?",Boolean.class,hold)).isFalse();assertThat(retention.scheduleDue()).isZero();UUID job=UUID.randomUUID();jdbc.update("INSERT INTO seal.retention_job(retention_job_id,consent_request_id,recipient_id,retention_policy_version_id,anchor_date,due_date,job_status,destruction_method,requested_at) VALUES(?,?,?,?,CURRENT_DATE,CURRENT_DATE,'DUE','DELETE',CURRENT_TIMESTAMP)",job,request.requestId(),recipient,fixture.retentionVersionId());retention.submit(requester,job);retention.approve(approver,job);UUID key=UUID.randomUUID();RetentionExecutionResult first=retention.execute(requester,job,key);RetentionExecutionResult repeated=retention.execute(requester,job,key);assertThat(repeated).isEqualTo(first);assertThat(first.recipientPiiDestroyed()).isTrue();assertThat(jdbc.queryForObject("SELECT recipient_status FROM seal.recipient WHERE recipient_id=?",String.class,recipient)).isEqualTo("DESTROYED");retention.confirm(approver,job);assertThat(retention.require(requester,job).status()).isEqualTo(RetentionJobStatus.CONFIRMED);}
 @Test void keepsAuditAndRightsRestrictionHoldsActiveAtTheSameTime(){UUID actor=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");Fixture fixture=publishedFixture(org,fixtureCreator(),actor);UUID recipient=recipients.create(new CreateRecipientCommand(actor,org,"보존 공존 대상자","hold-"+UUID.randomUUID()+"@example.com","공존 검증"));var request=requests.create(actor,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));retention.placeLegalHold(actor,request.requestId(),"AUDIT","감사 대응",LocalDate.now().plusDays(30));retention.placeRestrictionHold(request.requestId(),actor,Instant.now());retention.placeRestrictionHold(request.requestId(),actor,Instant.now());assertThat(jdbc.queryForObject("SELECT count(*) FROM seal.legal_hold WHERE consent_request_id=? AND active",Integer.class,request.requestId())).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM seal.legal_hold WHERE consent_request_id=? AND active AND hold_reason_code='AUDIT'",Integer.class,request.requestId())).isOne();assertThat(jdbc.queryForObject("SELECT count(*) FROM seal.legal_hold WHERE consent_request_id=? AND active AND hold_reason_code='RIGHTS_RESTRICTION'",Integer.class,request.requestId())).isOne();}
 private Fixture publishedFixture(UUID org,UUID creator,UUID approver){UUID retention=UUID.randomUUID(),retentionVersion=UUID.randomUUID(),activity=UUID.randomUUID(),activityVersion=UUID.randomUUID(),dataItem=UUID.randomUUID(),template=UUID.randomUUID(),templateVersion=UUID.randomUUID(),consentItem=UUID.randomUUID();String suffix=UUID.randomUUID().toString().substring(0,8).toUpperCase();jdbc.update("INSERT INTO seal.retention_policy(retention_policy_id,policy_code,policy_name,owner_organization_unit_id,created_by,updated_by) VALUES(?,?,?,?,?,?)",retention,"RT-RP-"+suffix,"파기 통합테스트 정책",org,creator,creator);jdbc.update("INSERT INTO seal.retention_policy_version(retention_policy_version_id,retention_policy_id,version_number,workflow_status,start_event,period_value,period_unit,destruction_method,created_by,review_requested_by,review_requested_at,approved_by,approved_at,updated_by) VALUES(?,?,1,'APPROVED','CONSENT_SUBMITTED_AT',3,'YEAR','DELETE',?,?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,?)",retentionVersion,retention,creator,creator,approver,approver);jdbc.update("UPDATE seal.retention_policy SET current_approved_version_id=? WHERE retention_policy_id=?",retentionVersion,retention);jdbc.update("INSERT INTO seal.processing_activity(processing_activity_id,activity_code,activity_name,owner_organization_unit_id,created_by,updated_by) VALUES(?,?,?,?,?,?)",activity,"RT-PA-"+suffix,"파기 통합테스트 업무",org,creator,creator);jdbc.update("INSERT INTO seal.processing_activity_version(processing_activity_version_id,processing_activity_id,version_number,workflow_status,processing_purpose,legal_basis_type,legal_basis_detail,retention_policy_version_id,created_by,review_requested_by,review_requested_at,approved_by,approved_at,updated_by) VALUES(?,?,1,'APPROVED','파기 통합테스트 목적','CONSENT','정보주체 명시적 동의',?,?,?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,?)",activityVersion,activity,retentionVersion,creator,creator,approver,approver);jdbc.update("UPDATE seal.processing_activity SET current_approved_version_id=? WHERE processing_activity_id=?",activityVersion,activity);jdbc.update("INSERT INTO seal.processing_data_item(processing_data_item_id,processing_activity_version_id,item_order,item_name,necessity_reason,required) VALUES(?,?,1,'이메일','동의 링크 발송 필요',TRUE)",dataItem,activityVersion);jdbc.update("INSERT INTO seal.consent_template(consent_template_id,template_code,template_name,processing_activity_id,created_by,updated_by) VALUES(?,?,?,?,?,?)",template,"RT-TPL-"+suffix,"파기 통합테스트 동의서",activity,creator,creator);jdbc.update("INSERT INTO seal.consent_template_version(consent_template_version_id,consent_template_id,processing_activity_id,processing_activity_version_id,version_number,workflow_status,title,introduction_html,review_requested_by,review_requested_at,approved_by,approved_at,published_by,published_at,content_hash,created_by,updated_by) VALUES(?,?,?,?,1,'PUBLISHED','파기 통합테스트 개인정보 동의서','<p>개인정보 처리 내용을 확인해 주세요.</p>',?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP,?,?,?)",templateVersion,template,activity,activityVersion,creator,approver,creator,"b".repeat(64),creator,creator);jdbc.update("UPDATE seal.consent_template SET current_published_version_id=? WHERE consent_template_id=?",templateVersion,template);jdbc.update("INSERT INTO seal.consent_item_definition(consent_item_definition_id,consent_template_version_id,processing_activity_version_id,item_order,item_code,item_type,item_title,required,purpose_text,retention_text,refusal_notice) VALUES(?,?,?,1,'COLLECT','COLLECTION_USE','개인정보 수집 이용 동의',TRUE,'파기 통합테스트 목적','동의 제출 후 3년','동의를 거부하면 신청이 제한될 수 있습니다.')",consentItem,templateVersion,activityVersion);jdbc.update("INSERT INTO seal.consent_item_data_selection(consent_item_definition_id,processing_activity_version_id,processing_data_item_id) VALUES(?,?,?)",consentItem,activityVersion,dataItem);return new Fixture(templateVersion,retentionVersion);}
 @Test void destroysCompletedSessionFlowAndFinalRightsMemos(){UUID requester=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='seal-admin'");UUID approver=id("SELECT admin_user_id FROM seal.admin_user WHERE login_id='vheraclesv'");UUID org=id("SELECT organization_unit_id FROM seal.organization_unit WHERE root_unit=TRUE");UUID creator=fixtureCreator();Fixture fixture=publishedFixture(org,creator,requester);UUID recipient=recipients.create(new CreateRecipientCommand(requester,org,"잔여정보 파기 대상자","residual-"+UUID.randomUUID()+"@example.com","잔여정보 파기 통합테스트"));var request=requests.create(requester,new CreateConsentRequestCommand(org,recipient,fixture.templateVersionId(),Instant.now().plusSeconds(7200),UUID.randomUUID()));UUID link=UUID.randomUUID();jdbc.update("INSERT INTO seal.secure_link(secure_link_id,consent_request_id,token_hmac,link_status,expires_at,issued_by,issued_at,completed_at) VALUES(?,?,?,'COMPLETED',CURRENT_TIMESTAMP+INTERVAL '1 hour',?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",link,request.requestId(),UUID.randomUUID().toString().replace("-","").repeat(2),requester);UUID session=UUID.randomUUID();jdbc.update("INSERT INTO seal.public_consent_session(public_consent_session_id,flow_hmac,consent_request_id,secure_link_id,session_status,expires_at,created_at,completed_at) VALUES(?,?,?,?,'COMPLETED',CURRENT_TIMESTAMP+INTERVAL '1 hour',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",session,"d".repeat(64),request.requestId(),link);UUID rights=UUID.randomUUID();jdbc.update("INSERT INTO seal.rights_request(rights_request_id,request_code,organization_unit_id,recipient_id,consent_request_id,rights_type,request_status,received_date,due_date,detail_ciphertext,result_note_ciphertext,encryption_key_id,created_by,created_at,completed_by,completed_at) VALUES(?,?,?,?,?,'ACCESS','COMPLETED',CURRENT_DATE,CURRENT_DATE,decode(repeat('aa',30),'hex'),decode(repeat('bb',30),'hex'),'v1',?,CURRENT_TIMESTAMP,?,CURRENT_TIMESTAMP)",rights,"RT-RR-"+rights.toString().substring(0,8),org,recipient,request.requestId(),requester,requester);UUID job=UUID.randomUUID();jdbc.update("INSERT INTO seal.retention_job(retention_job_id,consent_request_id,recipient_id,retention_policy_version_id,anchor_date,due_date,job_status,destruction_method,requested_at) VALUES(?,?,?,?,CURRENT_DATE,CURRENT_DATE,'DUE','DELETE',CURRENT_TIMESTAMP)",job,request.requestId(),recipient,fixture.retentionVersionId());retention.submit(requester,job);retention.approve(approver,job);RetentionExecutionResult result=retention.execute(requester,job,UUID.randomUUID());assertThat(result.sessionCount()).isEqualTo(1);assertThat(result.rightsCount()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT flow_hmac IS NULL FROM seal.public_consent_session WHERE public_consent_session_id=?",Boolean.class,session)).isTrue();assertThat(jdbc.queryForObject("SELECT detail_ciphertext IS NULL AND result_note_ciphertext IS NULL AND encryption_key_id IS NULL FROM seal.rights_request WHERE rights_request_id=?",Boolean.class,rights)).isTrue();}
 private UUID fixtureCreator(){UUID creator=UUID.randomUUID();jdbc.update("INSERT INTO seal.admin_user(admin_user_id,login_id,display_name,organization_unit_id,password_hash,must_change_password) SELECT ?,?,?,organization_unit_id,password_hash,FALSE FROM seal.admin_user WHERE login_id='seal-admin'",creator,"retention-fixture-"+creator.toString().substring(0,8),"파기 픽스처 작성자");return creator;}private UUID id(String sql){return jdbc.queryForObject(sql,UUID.class);}private record Fixture(UUID templateVersionId,UUID retentionVersionId){}
}
